        pressInNetL: real(payload.P2_L), // Обратка: нижнее предупреждение, бар
        pressInNetLL: real(payload.P2_LL), // Обратка: нижний аварийный порог, бар
    },

    // Temperature warning/alarm thresholds; decoder TE1/TE2 mean physical TE2/TE3
    temperatureThresholds: {
